          "props": {
            "level": 2,
            "text": "KS2 checking window"
          }
        },
        {
          "kind": "widget",
          "type": "richtext",
          "props": {
            "html": "\u003Cp\u003EThe KS2 checking exercise runs each year for primary schools. Review the provisional results for your school and submit amendments where the data looks wrong.\u003C/p\u003E"
          }
        }
      ]
    ]
  }
]

